package uz.mirix.tracelens.internal;
import jakarta.servlet.*;import jakarta.servlet.http.*;import java.io.*;
final class TraceLensHttpServletResponseWrapper extends HttpServletResponseWrapper {private long firstWriteNanos=-1;private ServletOutputStream outputStream;private PrintWriter writer;TraceLensHttpServletResponseWrapper(HttpServletResponse r){super(r);}long firstWriteNanos(){return firstWriteNanos;}private void markWrite(){if(firstWriteNanos<0)firstWriteNanos=System.nanoTime();}public ServletOutputStream getOutputStream()throws IOException{if(writer!=null)throw new IllegalStateException("getWriter() has already been called");if(outputStream==null){ServletOutputStream d=super.getOutputStream();outputStream=new ServletOutputStream(){public boolean isReady(){return d.isReady();}public void setWriteListener(WriteListener l){d.setWriteListener(l);}public void write(int b)throws IOException{markWrite();d.write(b);}public void write(byte[]b,int off,int len)throws IOException{markWrite();d.write(b,off,len);}public void flush()throws IOException{d.flush();}public void close()throws IOException{d.close();}};}return outputStream;}public PrintWriter getWriter()throws IOException{if(outputStream!=null)throw new IllegalStateException("getOutputStream() has already been called");if(writer==null){Writer d=super.getWriter();writer=new PrintWriter(new Writer(){public void write(char[]c,int off,int len)throws IOException{markWrite();d.write(c,off,len);}public void flush()throws IOException{d.flush();}public void close()throws IOException{d.close();}});}return writer;}}
